// === Tab: mySketch.js ===
let rings = [];
let stop=false 

function setup() 
{
  createCanvas(1500, 1000,WEBGL);
}

let counter=0

function draw() 
{
	if(stop==false)
	{
		counter++
		noFill();

		if (frameCount % 60 === 0 & counter<500) 
		{
			rings.push(new Ring(100, 100, 0));
		}

		if (rings.length > 9) 
		{
			rings.shift();
		}

		rings.forEach((ring) => 
		{
			ring.update();
		});
	}
}

class Ring 
{
  constructor(x, y, radius) 
	{
    this.x = x;
    this.y = y;
		let choice=round(random(1))
		if(choice==0) this.c=random(0,50)
		if(choice==1) this.c=random(200,255)
		this.rotateInc=0;
		this.size=round(random(3,20))
    this.radius = radius;

		this.fill1=random(255)
		this.fill2=random(255)
		this.fill3=random(255)
		this.fill4=.2
		this.choice=round(random(8))
  }
  update() 
	{
		this.rotateInc=0+.1
		push()
		rotateZ(this.rotateInc)
    this.radius += 1;
		stroke(this.c,this.c,this.c)
		translate(this.x,this.y,0)
		strokeWeight(1)

		if(counter==1950) stop=true
	//	if(this.choice==0) fill(this.fill1,this.fill2,this.fill3,this.fill4)
		torus(this.radius,this.radius*2,this.size)
		pop()
  }
}

